package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaNlDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujood)", "(Allah is) de Meest Verheerlijkte, de Meest Heilige, Heer van de engelen en de Geest (Djibril).", "In ruku en sujood.", "De Profeet ﷺ reciteerde dit in ruku en sujood."),
        "dua_sujood_dhanbi_kullah" to DuaText("In Sujood: Vergeef al mijn zonden", "O Allah, vergeef mij al mijn zonden – de kleine en de grote, de eerste en de laatste, de openlijke en de verborgen.", "In sujood.", "Uitputting is een plaats waar dua’s worden beantwoord."),
        "dua_sujood_ridaka" to DuaText("Toevlucht in uw plezier", "O Allah, ik zoek toevlucht bij Uw genoegen tegen Uw woede, bij Uw vergeving tegen Uw bestraffing, en ik zoek toevlucht bij U tegen U. Ik kan U niet volledig prijzen; Je bent zoals Je jezelf hebt geprezen.", "In sujood hoorde Aisha (RA) de Profeet ﷺ dit zeggen.", "Een sujood dua van de Profeet ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Alle verbale, fysieke en financiële daden van aanbidding zijn voor Allah. Vrede zij met u, O Profeet, en de genade van Allah en Zijn zegeningen. Vrede zij met ons en met de rechtschapen dienaren van Allah. Ik getuig dat niemand het recht heeft om aanbeden te worden behalve Allah, en ik getuig dat Mohammed ﷺ (vrede zij met hem) Zijn dienaar en boodschapper is.", "In elke zitting – verteld door Abdullah ibn Mas'ud (RA) (de Hanafi-praktijk).", "De Profeet ﷺ onderwees het als een soera van de Koran."),
        "dua_sajdah_tilawah" to DuaText("Sajdah van recitatie", "Mijn gezicht heeft zich ter aarde geworpen voor Degene die het heeft geschapen en het gehoor en zicht ervan heeft voortgebracht door Zijn macht en kracht.", "In de uitputting van recitatie.", "De Profeet ﷺ zei dit tijdens de nachtelijke recitatie."),
        "dua_after_witr" to DuaText("Na Witr", "Glorie zij de Koning, de Allerheiligste.", "Drie keer na de salam van witr, de derde keer de stem verheffend.", "De Profeet ﷺ zei dit na witr."),
        "dua_tahajjud_nur" to DuaText("Tahajjud opent smeekbede", "O Allah, aan U behoort de lof; Jij bent de Onderhouder van de hemel, de aarde en alles daarin. Aan U behoort lof; Jij bent het Licht van de hemel, de aarde en alles daarin. Aan U behoort lof; U bent de waarheid, uw belofte is waar, de ontmoeting met u is waar, uw woord is waar, het paradijs is waar, de hel is waar, de profeten zijn waar, Mohammed ﷺ is waar en het Uur is waar.", "Bij het begin van het nachtgebed (tahajjud) (het openingsgedeelte van de dua).", "De Profeet ﷺ reciteerde dit toen hij opstond voor tahajjud (de volledige dua staat in al-Bukhari)."),
        "dua_rabba_jibrail" to DuaText("Leid mij in betwiste zaken", "O Allah, Heer van Jibril, Mika'il en Israfil, Schepper van de hemelen en de aarde, Kenner van het ongeziene en het geziene! U zult tussen Uw dienaren oordelen over wat zij vroeger van mening verschilden. Leid mij met Uw toestemming naar de waarheid waarover meningsverschillen bestaan. U leidt inderdaad wie U wilt naar een recht pad.", "Aan het begin van tahajjud – voor begeleiding naar de waarheid te midden van onenigheid.", "De Profeet ﷺ begon zijn nachtgebed met deze dua."),
        "dua_going_to_mosque_nur" to DuaText("Naar de moskee gaan (Dua van licht)", "O Allah, plaats licht in mijn hart, licht in mijn ogen, licht in mijn oren, licht aan mijn rechterkant, licht aan mijn linkerkant, licht boven mij, licht onder mij, licht voor mij, licht achter mij, en maak licht voor mij.", "Terwijl je naar de moskee gaat voor Fajr.", "De Profeet ﷺ reciteerde dit toen hij uitging voor gebed."),
        "dua_waswasa_salah" to DuaText("Waswasa tijdens Salah (Khinzab)", "Ik zoek mijn toevlucht bij Allah tegen Shaytan, de vervloekte.", "Als er tijdens het gebed satanisch gefluister klinkt, zoek dan je toevlucht en spuug drie keer lichtjes naar links.", "Uthman ibn Abil-'As (RA) deed dit en het gefluister verdween."),
        "dua_alimal_ghayb" to DuaText("Kenner van het onzichtbare", "O Allah, Kenner van het onzichtbare en het zichtbare, Schepper van de hemelen en de aarde, Heer en Soeverein van alle dingen! Ik getuig dat er geen god is behalve Jij. Ik zoek mijn toevlucht bij U tegen het kwaad van mezelf, en tegen het kwaad van Shaytan en zijn (oproep tot) shirk.", "Ochtend, avond en voor het slapengaan – de Profeet ﷺ leerde het aan Abu Bakr (RA).", "Bescherming tegen het kwaad van het zelf en van Shaytan."),
        "dua_fitratil_islam" to DuaText("Op de Fitrah van de Islam", "We zijn de ochtend ingegaan op de fitrah van de islam, op het woord van oprechtheid, op de religie van onze profeet Mohammed ﷺ en op de weg van onze vader Ibrahim (AS), die oprecht en moslim was, en niet tot de polytheïsten behoorde.", "In de ochtend.", "Elke ochtend je geloof vernieuwen."),
        "dua_amsayna_fitrah" to DuaText("Avond op de Fitrah van de Islam", "We zijn de avond ingegaan met de fitrah van de islam, met het woord van oprechtheid, met de religie van onze profeet Mohammed ﷺ en met de weg van onze vader Ibrahim (AS), die oprecht en moslim was en niet tot de polytheïsten behoorde.", "In de avond.", "Elke avond je geloof vernieuwen."),
        "dua_tahleel_10_fajr" to DuaText("Tien Tahleel na Fajr en Maghrib", "Niemand heeft het recht om aanbeden te worden behalve Allah, alleen, zonder partner. Van Hem is de heerschappij en van Hem is de lof; Hij geeft leven en veroorzaakt de dood, en Hij heeft macht over alle dingen.", "Tien keer na Fajr (en Maghrib), voordat u stopt met zitten of spreken.", "Tien goede daden, tien zonden uitgewist, tien rangen verhoogd en de hele dag bescherming tegen Shaytan."),
        "dua_la_hawla_kanz" to DuaText("Een schat van Jannah", "Er is geen macht en geen macht behalve bij Allah.", "Vaak, altijd.", "Het is een van de schatten van het paradijs."),
        "dua_four_beloved_words" to DuaText("De vier meest geliefde woorden", "Glorie zij Allah, alle lof is voor Allah, niemand heeft het recht om aanbeden te worden behalve Allah, en Allah is de Grootste.", "De woorden die het meest geliefd zijn bij Allah.", "Ze zijn de Profeet ﷺ dierbaarder dan alles waar de zon opkomt."),
        "dua_two_light_words" to DuaText("Twee woorden licht op de tong", "Glorie zij Allah en alle lof is aan Hem; glorie zij Allah, de Grote.", "Licht op de tong, zwaar op de weegschaal.", "Geliefd bij de Barmhartige, licht op de tong en zwaar op de weegschaal. (De laatste hadith van al-Bukhari)"),
        "dua_ya_dhal_jalal" to DuaText("Ya Dhal-Jalali wal-Ikram", "O Bezitter van Majesteit en Eer!", "Houd je eraan vast in dua – de instructie van de Profeet ﷺ.", "De Profeet ﷺ zei: houd vast aan 'Ya Dhal-Jalali wal-Ikram'."),
        "dua_sleep_wadatu_janbi" to DuaText("In uw naam ga ik liggen", "In Uw naam, mijn Heer, leg ik mijn zijde neer en in Uw naam sta ik op. Als U mijn ziel wegneemt, heb er medelijden mee, en als U haar vrijlaat, bescherm haar dan zoals U Uw rechtvaardige dienaren beschermt.", "Na het bed afstoffen en gaan liggen.", "Het toevertrouwen van je ziel aan Allah voordat je gaat slapen."),
        "dua_sleep_khalaqta_nafsi" to DuaText("Jij hebt mijn ziel gecreëerd", "O Allah, U hebt mijn ziel geschapen en U zult haar nemen. Zijn dood en zijn leven behoren U toe. Als U het in leven houdt, bescherm het dan, en als U ervoor zorgt dat het sterft, vergeef het dan. O Allah, ik vraag U om welzijn.", "Voordat je gaat slapen – overgeleverd door Ibn Umar (RA).", "De Profeet ﷺ gaf opdracht dit voor het slapengaan te zeggen."),
        "dua_sleep_atamana" to DuaText("Dankbaarheid vóór het slapen gaan", "Alle lof komt toe aan Allah die ons te eten gaf, ons te drinken gaf, ons genoeg gaf en ons onderdak gaf. Hoevelen zijn er die niemand hebben die hen voldoende kan voorzien of onderdak kan bieden.", "Bij het naar bed gaan.", "De Profeet ﷺ zei dit toen hij naar bed ging."),
        "dua_sleep_rabbas_samawat" to DuaText("Heer van de hemel – Betaal onze schuld", "O Allah, Heer van de hemelen, de aarde en de Machtige Troon, onze Heer en Heer van alle dingen, Splitser van het zaad en de dadelsteen, Onthuller van de Thora, de Injil en de Furqan! Ik zoek mijn toevlucht bij U tegen het kwaad van alles waarvan U de spie vasthoudt. O Allah, U bent de Eerste, er is niets vóór U; Jij bent de Laatste, er is niets na jou; Jij bent het Manifest, er is niets boven jou; Jij bent de Verborgene, er is niets voor jou verborgen. Verlos onze schulden voor ons en bevrijd ons van de armoede.", "Voor het slapengaan, liggend op de rechterkant – geleerd aan Fatimah (RA).", "Een dua voor verlichting van schulden en ontberingen."),
        "dua_sleep_fear" to DuaText("Angst of ongemak tijdens de slaap", "Ik zoek toevlucht bij de perfecte woorden van Allah tegen Zijn woede en Zijn bestraffing, tegen het kwaad van Zijn dienaren, en tegen de influisteringen van de duivels en tegen hun komst naar mij.", "Wanneer u angst of ongemak voelt tijdens de slaap.", "Als je dat doet, zal dat ding hem geen kwaad doen."),
        "dua_waking_afani" to DuaText("Wakker worden: Hij herstelde mijn ziel", "Alle lof is voor Allah, die mijn lichaam welzijn gaf, mijn ziel aan mij teruggaf en mij toestond Hem te gedenken.", "Bij het ontwaken.", "Dankbaarheid voor een nieuwe ochtend."),
        "dua_allahu_rabbi" to DuaText("Allah, Allah is mijn Heer", "Allah, Allah is mijn Heer; Ik associeer niets met Hem.", "In verdriet of nood – de Profeet ﷺ leerde het aan Asma bint Umays (RA).", "Vasthouden aan tawhi in tijden van nood."),
        "dua_rahmataka_arju" to DuaText("Ik hoop op uw genade", "O Allah, het is Uw genade waar ik op hoop, dus laat mij niet aan mezelf over, zelfs niet voor een oogwenk, en zet al mijn zaken in orde. Er is geen god behalve Jij.", "De dua van degene in nood (Da'awat al-makrub).", "De Profeet ﷺ noemde het de dua van degene in nood."),
        "dua_against_enemy_ahzab" to DuaText("Tegen de legers van de vijand", "O Allah, Onthuller van het Boek, Snel in het afrekenen! Versla de bondgenoten. O Allah, versla ze en schud ze.", "Tegen de vijand – de dua van de Slag om de Zuidelijken.", "De ﷺ dua van de Profeet tegen de vijand."),
        "dua_anta_adudi" to DuaText("Jij bent mijn steun", "O Allah, U bent mijn steun en mijn helper. Door jou plan ik, door jou ga ik vooruit en door jou vecht ik.", "Vóór een wedstrijd of een grote uitdaging.", "De Profeet ﷺ zei dit in de strijd."),
        "dua_ikfinihim" to DuaText("Het volstaat mij tegen hen", "O Allah, ben mij voldoende tegen hen, hoe U ook wilt.", "Tegen het kwaad van de onderdrukkers – de dua van de jongen in het verhaal van de People of the Ditch.", "Allah redde de jongen van de onderdrukkers."),
        "dua_qadarullah" to DuaText("Als er iets ergs gebeurt", "Het is het besluit van Allah en Hij deed wat Hij wilde.", "Als er iets vervelends gebeurt, in plaats van te zeggen ‘als het maar’ is.", "'Als het maar' is, opent de deur voor Shaytan."),
        "dua_ala_kulli_hal" to DuaText("Lof in elke situatie", "Alle lof is voor Allah in elke situatie.", "Wanneer er iets niet leuks gebeurt.", "De Profeet ﷺ zei dit toen hij geconfronteerd werd met iets waar hij een hekel aan had."),
        "dua_dogs_barking" to DuaText("Honden horen blaffen 's nachts", "Ik zoek mijn toevlucht bij Allah tegen Shaytan, de vervloekte.", "Bij het horen van honden blaffen of een ezel balken in de nacht.", "Zij zien wat jij niet ziet."),
        "dua_leaving_home_adilla" to DuaText("Toevlucht tegen het dwalen", "O Allah, ik zoek toevlucht bij U, opdat ik niet afdwaal of op een dwaalspoor word gebracht, opdat ik niet uitglijd of gedwongen word uit te glijden, opdat ik geen kwaad doe of onrecht wordt aangedaan, opdat ik me niet dwaas gedraag of dwaas wordt behandeld.", "Bij het verlaten van het huis – verteld door Umm Salamah (RA).", "De Profeet ﷺ reciteerde dit telkens wanneer hij zijn huis verliet."),
        "dua_ascending_descending" to DuaText("Naar boven gaan en naar beneden komen", "Allah is de Grootste (bij het omhoog gaan). – Glorie zij Allah (bij het naar beneden komen).", "Zeg tijdens een reis 'Allahu Akbar' als je naar boven gaat en 'SubhanAllah' als je naar beneden gaat.", "De praktijk van de Metgezellen (RA) tijdens het reizen."),
        "dua_traveller_sahar" to DuaText("Reizigersdua vóór zonsopgang", "Een luisteraar heeft onze lof aan Allah en Zijn goede gunsten aan ons gehoord (en doorgegeven). Onze Heer, vergezel ons en schenk ons ​​Uw gunst – (ik zeg dit) zoek toevlucht bij Allah tegen het Vuur.", "Op reis, vóór zonsopgang.", "De Profeet ﷺ zei dit vóór zonsopgang tijdens het reizen."),
        "dua_zawwadakallah" to DuaText("Aan de reiziger: Moge Allah in Taqwa voorzien", "Moge Allah u voorzien van taqwa voor uw reis, uw zonden vergeven en het goede voor u gemakkelijk maken, waar u ook bent.", "Bij het afscheid nemen van een reiziger.", "De Profeet ﷺ gaf deze du aan iemand die op reis ging."),
        "dua_traveller_to_resident" to DuaText("Reiziger voor degenen die achterblijven", "Ik vertrouw je toe aan Allah, bij wie vertrouwen nooit verloren gaat.", "Gezegd door de reiziger bij het afscheid van familie.", "De veiligheid van het gezin aan Allah toevertrouwen."),
        "dua_entering_village" to DuaText("Een stad of dorp binnenkomen", "O Allah, Heer van de zeven hemelen en alles wat ze schaduw geven, Heer van de zeven aardes en alles wat ze dragen, Heer van de duivels en alles wat ze misleiden, Heer van de winden en alles wat ze verstrooien! Wij vragen U om het welzijn van deze stad en het welzijn van haar inwoners, en wij zoeken toevlucht bij U tegen haar kwaad, het kwaad van haar mensen en het kwaad van wat zich daarin bevindt.", "Voordat u een dorp of stad binnengaat.", "De Profeet ﷺ reciteerde dit telkens wanneer hij een stad wilde binnengaan."),
        "dua_vehicle_stumbles" to DuaText("Wanneer het voertuig struikelt", "In de naam van Allah.", "Wanneer het rijdier of het voertuig uitglijdt of struikelt, in plaats van te zeggen 'Moge Shaytan vergaan'.", "Het zeggen van Bismillah zorgt ervoor dat Shaytan krimpt tot de grootte van een vlieg."),
        "dua_ajz_kasal_haram" to DuaText("Toevlucht tegen zwakte en ouderdom", "O Allah, ik zoek toevlucht bij U tegen hulpeloosheid en luiheid, tegen lafheid en ouderdom, tegen de beproevingen van leven en dood, en tegen de bestraffing van het graf.", "Een uitgebreide dagelijkse dua van toevlucht.", "Een dua die de Profeet ﷺ vaak maakte."),
    )
}
